CREATE TABLE IF NOT EXISTS federation_controllers (controller_id VARCHAR(191) PRIMARY KEY,region_id VARCHAR(191),datacenter_id VARCHAR(191),endpoint TEXT NOT NULL,role VARCHAR(32) NOT NULL DEFAULT 'datacenter',status VARCHAR(32) NOT NULL DEFAULT 'unknown',priority INTEGER NOT NULL DEFAULT 100,capabilities_json LONGTEXT NOT NULL,last_seen_at VARCHAR(64),created_at VARCHAR(64) NOT NULL,updated_at VARCHAR(64) NOT NULL);
CREATE INDEX idx_federation_controllers_location ON federation_controllers(region_id,datacenter_id,status);
CREATE TABLE IF NOT EXISTS federation_credentials (credential_id VARCHAR(191) PRIMARY KEY,controller_id VARCHAR(191) NOT NULL,token_prefix VARCHAR(191) NOT NULL UNIQUE,secret_hash VARCHAR(128) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'active',expires_at VARCHAR(64),last_used_at VARCHAR(64),created_at VARCHAR(64) NOT NULL,revoked_at VARCHAR(64),CONSTRAINT fk_fedcred_controller FOREIGN KEY(controller_id) REFERENCES federation_controllers(controller_id) ON DELETE CASCADE);
CREATE INDEX idx_federation_credentials_controller ON federation_credentials(controller_id,status);
CREATE TABLE IF NOT EXISTS federation_request_nonces (controller_id VARCHAR(191) NOT NULL,nonce VARCHAR(191) NOT NULL,request_timestamp VARCHAR(64) NOT NULL,received_at VARCHAR(64) NOT NULL,PRIMARY KEY(controller_id,nonce),CONSTRAINT fk_fednonce_controller FOREIGN KEY(controller_id) REFERENCES federation_controllers(controller_id) ON DELETE CASCADE);
CREATE INDEX idx_federation_request_nonces_received ON federation_request_nonces(received_at);
CREATE TABLE IF NOT EXISTS federation_snapshots (snapshot_id VARCHAR(191) PRIMARY KEY,controller_id VARCHAR(191) NOT NULL,generated_at VARCHAR(64) NOT NULL,sequence BIGINT NOT NULL,checksum VARCHAR(128) NOT NULL,payload_json LONGTEXT NOT NULL,received_at VARCHAR(64) NOT NULL,UNIQUE KEY uq_fed_snapshot_sequence(controller_id,sequence),CONSTRAINT fk_fedsnapshot_controller FOREIGN KEY(controller_id) REFERENCES federation_controllers(controller_id) ON DELETE CASCADE);
CREATE INDEX idx_federation_snapshots_controller ON federation_snapshots(controller_id,sequence);
CREATE TABLE IF NOT EXISTS federation_routes (route_id VARCHAR(191) PRIMARY KEY,scope_type VARCHAR(32) NOT NULL,scope_id VARCHAR(191) NOT NULL,controller_id VARCHAR(191) NOT NULL,priority INTEGER NOT NULL DEFAULT 100,enabled BOOLEAN NOT NULL DEFAULT TRUE,metadata_json LONGTEXT NOT NULL,created_at VARCHAR(64) NOT NULL,updated_at VARCHAR(64) NOT NULL,UNIQUE KEY uq_fed_route(scope_type,scope_id,controller_id),CONSTRAINT fk_fedroute_controller FOREIGN KEY(controller_id) REFERENCES federation_controllers(controller_id) ON DELETE CASCADE);
CREATE INDEX idx_federation_routes_scope ON federation_routes(scope_type,scope_id,enabled,priority);
CREATE TABLE IF NOT EXISTS federation_event_cursors (controller_id VARCHAR(191) PRIMARY KEY,last_sequence BIGINT NOT NULL DEFAULT -1,last_event_id VARCHAR(191),updated_at VARCHAR(64) NOT NULL,CONSTRAINT fk_fedcursor_controller FOREIGN KEY(controller_id) REFERENCES federation_controllers(controller_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS federation_event_receipts (controller_id VARCHAR(191) NOT NULL,event_id VARCHAR(191) NOT NULL,checksum VARCHAR(128) NOT NULL,received_at VARCHAR(64) NOT NULL,PRIMARY KEY(controller_id,event_id),CONSTRAINT fk_fedreceipt_controller FOREIGN KEY(controller_id) REFERENCES federation_controllers(controller_id) ON DELETE CASCADE);
CREATE INDEX idx_federation_event_receipts_time ON federation_event_receipts(received_at);
CREATE TABLE IF NOT EXISTS federation_handoffs (handoff_id VARCHAR(191) PRIMARY KEY,request_id VARCHAR(191) NOT NULL UNIQUE,source_controller_id VARCHAR(191),target_controller_id VARCHAR(191) NOT NULL,instance_id VARCHAR(191) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'pending',checksum VARCHAR(128) NOT NULL,payload_json LONGTEXT NOT NULL,result_json LONGTEXT,created_at VARCHAR(64) NOT NULL,updated_at VARCHAR(64) NOT NULL,CONSTRAINT fk_fedhandoff_controller FOREIGN KEY(target_controller_id) REFERENCES federation_controllers(controller_id) ON DELETE RESTRICT);
CREATE INDEX idx_federation_handoffs_target_status ON federation_handoffs(target_controller_id,status,created_at);
